cmd:
mkdir -p /work/old-t8/system /work/old-t8/constant
cat << 'EOF' > /work/old-t8/system/controlDict
FoamFile
{
    version 2.0;
    format ascii;
    class dictionary;
    object controlDict;
}
application     chtMultiRegionFoam;
startFrom        startTime;
startTime        0;
stopAt           endTime;
endTime          1;
deltaT           1;
writeControl     timeStep;
writeInterval    1;
purgeWrite       0;
writeFormat      ascii;
writePrecision   6;
writeCompression off;
timeFormat       general;
timePrecision    6;
runTimeModifiable true;
EOF
cat << 'EOF' > /work/old-t8/system/fvSchemes
FoamFile { version 2.0; format ascii; class dictionary; object fvSchemes; }
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
EOF
cat << 'EOF' > /work/old-t8/system/fvSolution
FoamFile { version 2.0; format ascii; class dictionary; object fvSolution; }
solvers {}
EOF
cd /work/old-t8 && ./Allmesh 2>&1 | tail -100
